order_write.header_insert:
INSERT dbo.ORDER_TABLE
  (ORDER_ID_COLUMN, STORE_COLUMN, REVISION_COLUMN, YARD_COLUMN,
   ORDER_NUMBER_COLUMN, ACCOUNT_COLUMN, CUSTOMER_COLUMN, CREATED_BY_COLUMN,
   CREATED_DATE_COLUMN, ORDER_STATUS_COLUMN, NOTES_COLUMN, AMOUNT_COLUMN,
   IS_LAST_REVISION_COLUMN, PARTS_TOTAL_COLUMN, EXTERNAL_REFERENCE_COLUMN,
   APPLY_CUSTOMER_TAX_RATE_COLUMN, RECALCULATE_TAXES_COLUMN,
   FREIGHT_TOTAL_COLUMN, DISCOUNT_TOTAL_COLUMN, SHIP_METHOD_COLUMN,
   SHIP_NAME_COLUMN, SHIP_BUSINESS_NAME_COLUMN, SHIP_ADDRESS1_COLUMN,
   SHIP_ADDRESS2_COLUMN, SHIP_CITY_COLUMN, SHIP_STATE_COLUMN,
   SHIP_POSTAL_COLUMN, SHIP_COUNTRY_COLUMN, SHIP_PHONE_COLUMN, SHIP_EMAIL_COLUMN,
   BILL_BUSINESS_NAME_COLUMN, BILL_ADDRESS1_COLUMN, BILL_ADDRESS2_COLUMN,
   BILL_CITY_COLUMN, BILL_STATE_COLUMN, BILL_POSTAL_COLUMN, BILL_COUNTRY_COLUMN,
   BILL_PHONE_COLUMN, BILL_EMAIL_COLUMN)
VALUES
  (@order_id, @store, 0, @yard,
   @order_number, @account, @customer, @employee,
   GETDATE(), 'OPEN_STATUS_CODE', @note, @amount,
   1, @parts_total, @order_ref,
   @apply_rate, @recalc_tax,
   @freight, @discount, @ship_via,
   @ship_name, @ship_name, @ship_addr1,
   @ship_addr2, @ship_city, @ship_state,
   @ship_zip, @ship_ctry, @ship_phone, @ship_email,
   @bill_name, @bill_addr1, @bill_addr2,
   @bill_city, @bill_state, @bill_zip, @bill_ctry,
   @bill_phone, @bill_email)

order_write.line_insert:
INSERT dbo.ORDER_LINE_TABLE
  (LINE_ID_COLUMN, ORDER_ID_COLUMN, REVISION_COLUMN, LINE_STATUS_COLUMN,
   PART_ID_COLUMN, INTERCHANGE_NUMBER_COLUMN, LINE_DESCRIPTION_COLUMN,
   QUANTITY_COLUMN, QUANTITY_RESERVED_COLUMN, UNIT_PRICE_COLUMN,
   LINE_SUBTOTAL_COLUMN, LINE_TOTAL_COLUMN, LINE_DISCOUNT_COLUMN,
   DONOR_MODEL_YEAR_COLUMN, DONOR_MODEL_NAME_COLUMN, LINE_NOTES_COLUMN,
   IS_TAXABLE_COLUMN)
VALUES
  (@li_id, @order_id, 0, 'OPEN_STATUS_CODE',
   @li_rnum, @li_intch, @li_desc,
   @li_qty, @li_qty, @li_price,
   @li_sub, @li_total, @li_sub - @li_total,
   @li_year, @li_model, @li_notes, @taxable)
